-- All foundation-type samples with their inquiry metadata (read-only).
\copy (SELECT s.id AS sample_id, s.building_id::text AS building_id, s.inquiry_id, s.foundation_type::text AS foundation_type, (s.delete_date IS NOT NULL) AS sample_deleted, (i.delete_date IS NOT NULL) AS inquiry_deleted, i.type::text AS inquiry_type, i.document_date, i.create_date::date AS inquiry_create_date, s.create_date::date AS sample_create_date, i.attribution_id, date_part('year', s.built_year::date)::int AS sample_built_year, date_part('year', b.built_year::date)::int AS bag_built_year FROM report.inquiry_sample s JOIN report.inquiry i ON i.id = s.inquiry_id LEFT JOIN geocoder.building b ON b.external_id = s.building_id::text) TO 'data/samples.csv' WITH CSV HEADER
